@import "tailwindcss";
@import "tw-animate-css";

@custom-variant dark (&:is(.dark *));

:root {
  --background: oklch(1 0 0);
  --foreground: oklch(0.1788 0.0047 264.45);

  /* Card: rgb(240,240,240) — browser-extracted from the original site/jaydwivedi */
  /* Energetic uses bg color contrast for cards, zero shadow anywhere */
  --card: oklch(0.9542 0 0);
  --card-foreground: oklch(0.1788 0.0047 264.45);

  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.1788 0.0047 264.45);

  --primary: oklch(0.2244 0.0039 264.49);
  --primary-foreground: oklch(1 0 0);

  --secondary: oklch(0.9619 0 0);
  --secondary-foreground: oklch(0.2244 0.0039 264.49);

  --muted: oklch(0.9696 0 0);
  --muted-foreground: oklch(0.5547 0 0);

  --accent: oklch(0.9696 0 0);
  --accent-foreground: oklch(0.2244 0.0039 264.49);

  --destructive: oklch(0.6356 0.2082 25.38);
  --destructive-foreground: oklch(1 0 0);

  --border: oklch(0.9234 0 0);
  --input: oklch(0.9234 0 0);
  --ring: oklch(0.2244 0.0039 264.49);
  --radius: 0.875rem;

  /* Shadow overrides — light theme: minimal, borderless aesthetic */
  --shadow-2xs: 0 1px 2px 0 rgba(0,0,0,0.04);
  --shadow-xs:  0 1px 2px 0 rgba(0,0,0,0.06);
  --shadow-sm:  0 1px 3px 0 rgba(0,0,0,0.07), 0 1px 2px -1px rgba(0,0,0,0.05);
  --shadow:     0 1px 3px 0 rgba(0,0,0,0.08), 0 1px 2px -1px rgba(0,0,0,0.06);
  --shadow-md:  0 4px 6px -1px rgba(0,0,0,0.08), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg:  0 8px 16px -2px rgba(0,0,0,0.08), 0 0 0 1px rgba(0,0,0,0.04);
  --shadow-xl:  0 16px 24px -4px rgba(0,0,0,0.1), 0 0 0 1px rgba(0,0,0,0.04);
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/50;
  }
  html {
    font-family: var(--font-geist-sans), ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  }
  body {
    @apply bg-background text-foreground antialiased;
  }
}
